<template><div class="app-container"><h2>散货配货配置</h2><el-alert title="白散货和彩散货共用规格表。按形状、颜色（彩散货）、mm维护单粒ct、两档价格及粒数库存，无需填写商品资料。" :closable="false"/><el-tabs v-model="category" @tab-click="load"><el-tab-pane name="loose_white" label="培白散货"/><el-tab-pane name="loose_color" label="培彩散货"/></el-tabs><el-button @click="load">刷新</el-button><el-button v-if="canEdit" type="primary" @click="edit()">新增配货配置</el-button><loose-price-import :can-edit="canEdit" @imported="load"/><el-table v-loading="loading" :data="lines" border style="margin-top:20px"><el-table-column prop="shape" label="形状"/><el-table-column v-if="category==='loose_color'" prop="color" label="颜色"/><el-table-column prop="size" label="尺寸 mm"/><el-table-column prop="weight" label="单粒 ct"/><el-table-column prop="clarity" label="净度"/><el-table-column prop="price" label="元/ct"/><el-table-column prop="stock" label="库存（粒）"/><el-table-column label="状态"><template slot-scope="{row}">{{ row.enabled?'可售':'停用' }}</template></el-table-column><el-table-column label="操作"><template slot-scope="{row}"><el-button v-if="canEdit" type="text" @click="edit(row.product)">编辑配货配置</el-button></template></el-table-column></el-table><el-dialog title="散货规格价格表" :visible.sync="visible" width="94%" :close-on-click-modal="false"><el-switch v-model="enabled" active-text="开放配货"/><loose-editor ref="editor" :shapes="shapes" :colors="colors" :colored="category==='loose_color'"/><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button :loading="saving" type="primary" @click="save">保存配置</el-button></span></el-dialog></div></template>
<script>
import LooseEditor from './LooseEditor'
import LoosePriceImport from './LoosePriceImport'
import {diamondGet,diamondPost} from '@/api/diamond'
export default{
 components:{LooseEditor,LoosePriceImport},data(){return{category:'loose_white',categories:[],shapes:[],colors:[],products:[],loading:false,saving:false,visible:false,product:null,enabled:true}},
 computed:{canEdit(){try{return JSON.parse(localStorage.getItem('permissionsList')||'[]').includes('DiamondGoodsEdit')}catch(e){return false}},lines(){return this.products.filter(product=>product.categories.some(item=>item.code===this.category)).reduce((rows,product)=>rows.concat(product.skus.map(sku=>({product,shape:sku.spec&&sku.spec.shape||'圆形',color:sku.spec&&sku.spec.color,size:sku.spec&&sku.spec.size_mm,weight:sku.spec&&sku.spec.unit_weight_ct,clarity:sku.spec&&sku.spec.clarity,price:sku.price,stock:sku.stock,enabled:product.enabled&&sku.enabled}))),[])}},
 created(){this.load()},methods:{async load(){this.loading=true;try{const data=await Promise.all([diamondGet('categories'),diamondGet('shapes'),diamondGet('colors')]);this.categories=data[0].data;this.shapes=data[1].data;this.colors=data[2].data;let page=1,res;const products=[];do{res=(await diamondGet('products',{product_type:'loose',page})).data;products.push(...res.data);page++}while(res.next_page_url);this.products=products}finally{this.loading=false}},edit(product){this.product=product?JSON.parse(JSON.stringify(product)):null;this.enabled=product?product.enabled:true;this.visible=true;this.$nextTick(()=>{try{const skus=this.product?this.product.skus:[];skus.forEach(sku=>{sku.original_stock=sku.stock;sku.price=Number(sku.price)});this.$refs.editor.open(skus)}catch(error){this.$message.error(error.message);this.visible=false}})},async save(){this.saving=true;try{const category=this.categories.find(item=>item.code===this.category);if(!category)throw new Error('请先启用对应散货分类');const payload={product_type:'loose',categories:[category.id],enabled:this.enabled,skus:this.$refs.editor.value()};if(this.product)Object.assign(payload,{id:this.product.id,name:this.product.name,goods_no:this.product.goods_no,pics:this.product.pics,description:this.product.description,commission_rate:this.product.commission_rate});await diamondPost('products',payload);this.visible=false;this.$message.success('配货配置已保存');await this.load()}catch(error){this.$message.error(error.message||'保存失败')}finally{this.saving=false}}}}
</script>
